"""The champion snapshot (champions.json, generated by scripts/update_loldle_champions.py)."""

from __future__ import annotations

import json
import unicodedata
from dataclasses import asdict, dataclass
from functools import lru_cache
from pathlib import Path

DATA = Path(__file__).with_name("champions.json")


@dataclass(frozen=True)
class Champion:
    id: str
    name: str
    positions: tuple[str, ...]
    classes: tuple[str, ...]
    range: str
    resource: str
    region: str
    year: int
    spells: tuple[str, ...]
    splash: str

    def to_json(self) -> dict:
        return asdict(self)

    @classmethod
    def from_json(cls, d: dict) -> Champion:
        return cls(
            id=d["id"],
            name=d["name"],
            positions=tuple(d["positions"]),
            classes=tuple(d["classes"]),
            range=d["range"],
            resource=d["resource"],
            region=d["region"],
            year=int(d["year"]),
            spells=tuple(d["spells"]),
            splash=d["splash"],
        )


def normalise(text: str) -> str:
    """`Kai'Sa`, `kaisa` and `KAÏSA` are the same search."""
    decomposed = unicodedata.normalize("NFKD", text)
    return "".join(ch for ch in decomposed.casefold() if ch.isalnum())


@lru_cache(maxsize=1)
def load() -> dict[str, Champion]:
    rows = json.loads(DATA.read_text(encoding="utf-8"))
    return {r["id"]: Champion.from_json(r) for r in rows}


def search(text: str, limit: int = 25) -> list[Champion]:
    """Autocomplete: names starting with the text first, then names containing it."""
    q = normalise(text)
    champions = sorted(load().values(), key=lambda c: normalise(c.name))
    if not q:
        return champions[:limit]
    starts = [c for c in champions if normalise(c.name).startswith(q)]
    contains = [c for c in champions if q in normalise(c.name) and c not in starts]
    return (starts + contains)[:limit]


def find(text: str) -> Champion | None:
    """An exact id or name only: a partial word must not silently become a guess."""
    q = normalise(text)
    if not q:
        return None
    return next((c for c in load().values() if q in (normalise(c.id), normalise(c.name))), None)
